-- Bakery demo data. Everything here is made up: the bakery, its shops, products, prices and sales.
-- Weekly sales for two shops, January to June 2026. The demo analyst reads it with SQLite.
CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, price REAL NOT NULL);
CREATE TABLE stores (id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL);
CREATE TABLE weekly_sales (week_start TEXT NOT NULL, store_id INTEGER NOT NULL REFERENCES stores(id), product_id INTEGER NOT NULL REFERENCES products(id), units INTEGER NOT NULL, revenue REAL NOT NULL, PRIMARY KEY (week_start, store_id, product_id));
